#pragma once
namespace AIEdgeAuth {
constexpr char passwordPage[] = R"HTML(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AIEdge — Website password</title>
<style>:root{color-scheme:light dark;font:16px/1.5 system-ui;--bg:#f3f6f7;--card:#fff;--text:#182b34;--line:#bbc9cf}html[data-theme=dark]{--bg:#101c22;--card:#1b2c35;--text:#e7f0f3;--line:#536c79;color-scheme:dark}html[data-theme=light]{color-scheme:light}@media(prefers-color-scheme:dark){html:not([data-theme=light]){--bg:#101c22;--card:#1b2c35;--text:#e7f0f3;--line:#536c79}}*{box-sizing:border-box}body{margin:0;padding:24px;background:var(--bg);color:var(--text)}main{max-width:620px;margin:24px auto;padding:28px;background:var(--card);border-radius:18px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{margin:0}h2{margin-top:28px}label{display:block;margin-top:18px}input,button,select{font:inherit;color:inherit;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:10px}input{width:100%}.password{position:relative}.password input{padding-right:52px}.eye{position:absolute;right:4px;top:4px;border:0;padding:7px}.eye svg{display:block}button[type=submit]{width:100%;margin-top:24px}#status{min-height:1.5em}small{display:block;margin-top:8px}header label{margin:0;font-size:.9rem}a{color:inherit}</style>
<main><header><h1>AIEdge</h1><label>Theme <select id="theme"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label></header><h2>Change website password</h2><p>Changing this password signs out clients using the old password. Wi-Fi settings and SD files stay unchanged.</p><form id="form"><label for="current">Current website password</label><input id="current" type="password" required autocomplete="current-password"><label for="password">New website password</label><div class="password"><input id="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><button class="eye" type="button" id="show" aria-label="Show password" aria-pressed="false"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div><small>Use at least 12 characters. The sign-in username is <strong>admin</strong>.</small><label for="confirm">Confirm password</label><input id="confirm" type="password" required autocomplete="new-password"><button type="submit" id="save">Change password</button></form><p id="status" role="status" aria-live="polite"></p><a href="/" id="continue" hidden>Continue to AIEdge</a><small>Use a trusted local network. This HTTP connection is not encrypted.</small></main>
<script>const $=id=>document.getElementById(id);const theme=$('theme');function apply(v){document.documentElement.dataset.theme=v;theme.value=v}try{apply(localStorage.getItem('aiedge-device-theme')||'system')}catch(e){apply('system')}theme.onchange=()=>{apply(theme.value);try{localStorage.setItem('aiedge-device-theme',theme.value)}catch(e){}};$('show').onclick=()=>{const show=$('password').type==='password';for(const id of ['current','password','confirm'])$(id).type=show?'text':'password';$('show').setAttribute('aria-label',show?'Hide password':'Show password');$('show').setAttribute('aria-pressed',String(show))};$('form').onsubmit=async e=>{e.preventDefault();const p=$('password').value;if(p!==$('confirm').value){$('status').textContent='Passwords do not match.';return}if(new TextEncoder().encode(p).length>128){$('status').textContent='Password exceeds 128 UTF-8 bytes.';return}$('save').disabled=true;$('status').textContent='Saving…';try{const bytes=new TextEncoder().encode('admin:'+$('current').value);const auth=btoa(String.fromCharCode(...bytes));const r=await fetch('/auth/password',{method:'POST',headers:{'Authorization':'Basic '+auth,'X-AIEdge-Password-Change':'confirm','Content-Type':'text/plain;charset=UTF-8'},body:p});const text=await r.text();$('status').textContent=text;if(r.ok){$('form').hidden=true;for(const id of ['current','password','confirm'])$(id).value='';$('continue').hidden=false}}catch(e){$('status').textContent='Connection lost. Reload the page to check whether the password changed before trying again.'}finally{$('save').disabled=false}};</script></html>)HTML";
}
